def maxSumLengthRange(nums, lo, hi):
    from collections import deque
    n = len(nums)
    P = [0] * (n + 1)
    for i, x in enumerate(nums):
        P[i + 1] = P[i] + x
    dq = deque()
    best = None
    for j in range(lo, n + 1):
        i = j - lo
        while dq and P[dq[-1]] >= P[i]:
            dq.pop()
        dq.append(i)
        while dq[0] < j - hi:
            dq.popleft()
        cand = P[j] - P[dq[0]]
        if best is None or cand > best:
            best = cand
    return best
